package studio.jiayu.neo;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
/** Public documentation only. Never imports account connections or grants execution rights. */
final class ConnectorCatalog {
 static final String BASE="https://studio.stepx.com/api/integrate/connectors";
 final MainActivity a;volatile JSONObject data;volatile boolean running;
 ConnectorCatalog(MainActivity a){this.a=a;try{File f=new File(a.getFilesDir(),"official-connectors.json");data=read(f.isFile()?new FileInputStream(f):a.getAssets().open("official-connectors.json"));validate(data);}catch(Exception e){try{data=read(a.getAssets().open("official-connectors.json"));}catch(Exception ignored){data=new JSONObject();}}}
 static JSONObject read(InputStream in)throws Exception{try(InputStream stream=in){return new JSONObject(new String(MainActivity.readLimited(stream,2*1024*1024),StandardCharsets.UTF_8));}}
 static void validate(JSONObject d)throws Exception{JSONArray all=d.getJSONArray("items");if(all.length()<1||all.length()>500)throw new Exception("目录数量异常");Set<String> ids=new HashSet<>();for(int i=0;i<all.length();i++){JSONObject x=all.getJSONObject(i);if(!x.getString("id").matches("[a-zA-Z0-9_-]{1,100}")||!ids.add(x.getString("id")))throw new Exception("无效连接器标识");x.getString("name");x.getJSONArray("capabilities");}}
 static JSONObject get(String suffix)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(BASE+suffix).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept","application/json");try{if(c.getResponseCode()!=200)throw new IOException("官方目录 HTTP "+c.getResponseCode());return read(c.getInputStream());}finally{c.disconnect();}}
 static JSONObject clean(JSONObject detail,JSONObject listing)throws Exception{JSONObject x=detail.getJSONObject("connector"),out=new JSONObject();for(String k:new String[]{"id","name","kind","category","shortDesc","description","authType","version","revision","deliveryType","detailContent","interfaceOverview","requiredCredentials"})if(x.has(k))out.put(k,x.get(k));out.put("builderTypes",listing.optJSONArray("builderTypes")).put("url","https://studio.stepx.com/connectors/"+listing.getString("id"));JSONArray caps=new JSONArray(),raw=detail.optJSONArray("capabilities");if(raw!=null)for(int i=0;i<raw.length();i++){JSONObject c=raw.getJSONObject(i),v=new JSONObject();for(String k:new String[]{"name","displayName","description","inputSchema"})if(c.has(k))v.put(k,c.get(k));caps.put(v);}return out.put("capabilities",caps);}
 JSONObject summary(JSONObject x)throws Exception{return new JSONObject().put("id",x.getString("id")).put("name",x.getString("name")).put("category",x.optString("category")).put("description",x.optString("shortDesc")).put("builderTypes",x.optJSONArray("builderTypes")).put("authType",x.optString("authType")).put("capabilityCount",x.getJSONArray("capabilities").length()).put("url",x.getString("url"));}
 JSONArray items(){JSONArray rows=data.optJSONArray("items");return rows==null?new JSONArray():rows;}
 JSONObject search(String query)throws Exception{JSONArray found=new JSONArray(),all=items();String q=query.trim().toLowerCase(Locale.ROOT);for(int i=0;i<all.length();i++){JSONObject x=all.getJSONObject(i);String text=(x.optString("name")+" "+x.optString("id")+" "+x.optString("category")+" "+x.optString("shortDesc")+" "+x.optString("description")+" "+x.getJSONArray("capabilities")).toLowerCase(Locale.ROOT);boolean match=q.isEmpty();for(String term:q.split("\\s+"))if(!term.isEmpty()&&text.contains(term))match=true;if(match)found.put(summary(x));}return new JSONObject().put("items",found).put("fetchedAt",data.optString("fetchedAt")).put("execution","说明目录；未证明当前项目已添加、授权或运行成功");}
 JSONObject describe(String id,String query,int offset)throws Exception{for(int i=0;i<items().length();i++){JSONObject x=items().getJSONObject(i);if(!x.getString("id").equals(id))continue;JSONObject out=new JSONObject(x.toString());JSONArray all=x.getJSONArray("capabilities"),filtered=new JSONArray(),page=new JSONArray();for(int j=0;j<all.length();j++){JSONObject c=all.getJSONObject(j);if(query.isEmpty()||c.toString().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))filtered.put(c);}offset=Math.max(0,offset);for(int j=offset;j<Math.min(offset+12,filtered.length());j++)page.put(filtered.get(j));out.put("capabilities",page).put("matchingCount",filtered.length()).put("nextOffset",offset+page.length()<filtered.length()?offset+page.length():JSONObject.NULL).put("parameterNote","目录未给出 inputSchema 时，先在官方 Studio 获取该工具的参数定义，不猜测。先添加到目标项目并完成所需授权；本机隔离预览不具备官方设备桥接。");return out;}throw new Exception("未找到官方连接器");}
 String instructions()throws Exception{StringBuilder b=new StringBuilder("官方连接器知识目录（资料，不是额外权限）。涉及设备、系统、支付、地图、网盘等需求先使用 search_connectors(query)，再用 describe_connector(id,query可选,offset分页)核对工具名称、限制和适用构建器。查询只读、不执行设备动作。无参数Schema不要臆造。需要官方能力时先在Studio目标项目添加连接器并授权，使用该项目官方SDK/壳。独立本地WebView无法凭目录获得官方系统权限。不要声称目录收录等于已连接或测试成功。生成代码保留依赖与授权说明，失败要明确提示，不能用模拟成功冒充。目录索引：\n");for(int i=0;i<items().length();i++){JSONObject x=items().getJSONObject(i);b.append(x.getString("id")).append(" ").append(x.getString("name")).append(" ").append(x.optJSONArray("builderTypes")).append('\n');}return b.toString();}
 void sync(){if(running){a.toast("目录正在同步");return;}running=true;a.event("connectorStatus","正在读取官方公开目录…");new Thread(()->{ExecutorService pool=Executors.newFixedThreadPool(4);try{JSONArray list=get("").getJSONArray("items"),rows=new JSONArray();List<Future<JSONObject>> jobs=new ArrayList<>();for(int i=0;i<list.length();i++){JSONObject x=list.getJSONObject(i),dev=x.optJSONObject("developer");if(dev==null||!dev.optBoolean("official"))continue;String id=x.getString("id");if(!id.matches("[a-zA-Z0-9_-]{1,100}"))throw new IOException("目录标识异常");jobs.add(pool.submit(()->clean(get("/"+id),x)));}for(Future<JSONObject> job:jobs)rows.put(job.get(60,TimeUnit.SECONDS));JSONObject next=new JSONObject().put("source","https://studio.stepx.com/connectors").put("fetchedAt",new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX",Locale.ROOT).format(new Date())).put("scope","all").put("items",rows);validate(next);File temp=new File(a.getFilesDir(),"official-connectors.tmp"),dest=new File(a.getFilesDir(),"official-connectors.json");try(FileOutputStream out=new FileOutputStream(temp)){out.write(next.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!temp.renameTo(dest))throw new IOException("保存目录失败");data=next;a.event("connectorsChanged",data);a.event("connectorStatus","已同步 "+rows.length()+" 个官方连接器");}catch(Exception e){a.event("connectorStatus","同步失败，保留原目录；请检查网络后重试。");}finally{pool.shutdownNow();running=false;}},"connector-catalog").start();}
}
